const{assert,base,launch,ready,freeze}=require('./transcribe-guide-test-helpers.cjs');
(async()=>{const browser=await launch();try{for(const width of [1440,390]){const page=await browser.newPage({viewport:{width,height:900},reducedMotion:'reduce'});await page.goto(base+'quick-start/#find/pan');await ready(page);await page.emulateMedia({reducedMotion:'no-preference'});await page.locator('[data-guide-playback]').click();
 await page.waitForFunction(()=>document.getElementById('guide-camera').dataset.demoPhase==='panning-timeline');const start=Number(await page.locator('[data-guide-mockup]').getAttribute('data-demo-view-start'));await page.waitForTimeout(200);assert(Number(await page.locator('[data-guide-mockup]').getAttribute('data-demo-view-start'))>start);await freeze(page);assert.equal(await page.locator('#transcribe-seek').inputValue(),'3');assert.equal(await page.locator('#transcribe-selection-only').getAttribute('aria-pressed'),'false');
 await page.locator('.guide-topics [data-guide-lesson="open"]').click();await ready(page);assert.equal(await page.locator('#transcribe-file-name').textContent(),'Open audio');console.log(`${width}px: overview pan, held playhead, no early highlight, pause and cancellation passed`);await page.close();}}finally{await browser.close()}})().catch(e=>{console.error(e);process.exitCode=1});
